class Solution:
    def almostPalindromic(self, s: str) -> int:
        n = len(s)
        if n < 2:
            return n

        max_len = 1

        # every center: (i, i) for odd length, (i, i+1) for even length
        for i in range(n):
            for j in [i, i+1]:
                if j >= n:
                    continue

                l, r = i, j

                # phase 1: plain palindrome expansion; the core is s[l+1 .. r-1]
                while l >= 0 and r < n and s[l] == s[r]:
                    l -= 1
                    r += 1

                current_pal_len = r - l - 1

                # a palindrome is itself almost-palindromic
                if current_pal_len > max_len:
                    max_len = current_pal_len

                # phase 2a: delete s[l], then keep expanding from (l-1, r)
                if l >= 0:
                    if current_pal_len + 1 > max_len:
                        max_len = current_pal_len + 1

                    l_ext, r_ext = l - 1, r
                    while l_ext >= 0 and r_ext < n and s[l_ext] == s[r_ext]:
                        l_ext -= 1
                        r_ext += 1

                    # core + the deleted char + two per new matching pair
                    pairs = (l - 1) - l_ext
                    total_len = current_pal_len + 2 * pairs + 1
                    if total_len > max_len:
                        max_len = total_len

                # phase 2b: delete s[r], then keep expanding from (l, r+1)
                if r < n:
                    if current_pal_len + 1 > max_len:
                        max_len = current_pal_len + 1

                    l_ext, r_ext = l, r + 1
                    while l_ext >= 0 and r_ext < n and s[l_ext] == s[r_ext]:
                        l_ext -= 1
                        r_ext += 1

                    pairs = r_ext - (r + 1)
                    total_len = current_pal_len + 2 * pairs + 1
                    if total_len > max_len:
                        max_len = total_len

        return max_len

