/**
 * @param {string} s
 * @return {number}
 */
var almostPalindromic = function(s) {
    const n = s.length;
    if (n === 0) return 0;
    let maxLen = 1;
    // prev[j] = min deletions for s[i+1..j]; cur[j] = min deletions for s[i..j]
    let prev = new Array(n).fill(0);
    for (let i = n - 2; i >= 0; i--) {
        const cur = new Array(n).fill(0);
        cur[i] = 0;
        for (let j = i + 1; j < n; j++) {
            let val;
            if (s[i] === s[j]) {
                // matching ends cost nothing; inside is s[i+1..j-1]
                val = (j === i + 1) ? 0 : prev[j - 1];
            } else {
                // delete s[i] (prev[j]) or s[j] (cur[j-1])
                val = 1 + Math.min(prev[j], cur[j - 1]);
            }
            cur[j] = val;
            // at most one deletion: the substring qualifies
            if (val <= 1) {
                maxLen = Math.max(maxLen, j - i + 1);
            }
        }
        prev = cur;
    }
    return maxLen;
};

